        if 0 <= r - 2 < h:
            for cc in range(max(0, c - 2), min(w, c + 3)):
                out[r - 2][cc] = 5
        if 0 <= r - 1 < h and c - 2 >= 0:
            out[r - 1][c] = 5
        for dr in (-1, 0, 1):
            rr = r + dr
            for dc in (-2, 2):
                cc = c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 2
        rr = r + 2
        if 0 <= rr < h:
            out[rr] = [2] * w
            for cc in range(max(0, c - 2), min(w, c + 3)):
                out[rr][cc] = 8
    return out

